CREATE TABLE "Page" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "title" TEXT NOT NULL DEFAULT '', "subtitle" TEXT NOT NULL DEFAULT '', "heroMediaId" TEXT, "seoTitle" TEXT NOT NULL DEFAULT '', "seoDescription" TEXT NOT NULL DEFAULT '', "published" BOOLEAN NOT NULL DEFAULT false, "displayOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Page_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Page_slug_key" ON "Page"("slug"); CREATE INDEX "Page_published_idx" ON "Page"("published"); CREATE INDEX "Page_displayOrder_idx" ON "Page"("displayOrder");
ALTER TABLE "Page" ADD CONSTRAINT "Page_heroMediaId_fkey" FOREIGN KEY ("heroMediaId") REFERENCES "Media"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "PageSection" ("id" TEXT NOT NULL, "pageId" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL DEFAULT '', "subtitle" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL DEFAULT '', "mediaId" TEXT, "buttonText" TEXT, "buttonUrl" TEXT, "displayOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PageSection_pkey" PRIMARY KEY ("id"));
CREATE INDEX "PageSection_pageId_displayOrder_idx" ON "PageSection"("pageId", "displayOrder"); ALTER TABLE "PageSection" ADD CONSTRAINT "PageSection_pageId_fkey" FOREIGN KEY ("pageId") REFERENCES "Page"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PageSection" ADD CONSTRAINT "PageSection_mediaId_fkey" FOREIGN KEY ("mediaId") REFERENCES "Media"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "PageSectionItem" ("id" TEXT NOT NULL, "sectionId" TEXT NOT NULL, "title" TEXT NOT NULL DEFAULT '', "subtitle" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL DEFAULT '', "mediaId" TEXT, "link" TEXT, "displayOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PageSectionItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "PageSectionItem_sectionId_displayOrder_idx" ON "PageSectionItem"("sectionId", "displayOrder"); ALTER TABLE "PageSectionItem" ADD CONSTRAINT "PageSectionItem_sectionId_fkey" FOREIGN KEY ("sectionId") REFERENCES "PageSection"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PageSectionItem" ADD CONSTRAINT "PageSectionItem_mediaId_fkey" FOREIGN KEY ("mediaId") REFERENCES "Media"("id") ON DELETE SET NULL ON UPDATE CASCADE;
